const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Jabal Qidr: Approximately (25.13°N, 38.45°E)
  const jabalQidr = ee.Geometry.Point([38.45, 25.13]).buffer(500); // 500m buffer

  // Jabal Bayda: Approximately (25.32°N, 38.33°E)
  const jabalBayda = ee.Geometry.Point([38.33, 25.32]).buffer(500); // 500m buffer

  const startDate = '2024-04-01';
  const endDate = '2024-05-01'; // Up to but not including May 1st

  // Function to mask clouds in Sentinel-2 SR data.
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to 0-1 reflectance
  }

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(jabalQidr.merge(jabalBayda))
    .map(maskS2clouds)
    .select('B4'); // Select Red band (B4) for color comparison (lower value = darker)

  const colSize = collection.size().getInfo();
  if (colSize === 0) {
    console.log("No Sentinel-2 images found for April 2024.");
    // Fallback to Landsat 9
    collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_SR')
      .filterDate(startDate, endDate)
      .filterBounds(jabalQidr.merge(jabalBayda))
      .map(image => image.select('SR_B4').multiply(0.0000275).add(-0.2).rename('B4')); // Scale Landsat 9 Red band

    const landsatColSize = collection.size().getInfo();
    if (landsatColSize === 0) {
      console.log("No Sentinel-2 or Landsat 9 images found for April 2024.");
      console.log("C1");
      return;
    }
    console.log(`Using Landsat 9 (Images: ${landsatColSize})`);
  } else {
    console.log(`Using Sentinel-2 (Images: ${colSize})`);
  }

  // Create a median composite image
  const medianImage = collection.median();

  // 3. Processing & Calculation for Jabal Qidr
  const qidrCount = medianImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: jabalQidr,
    scale: 100, // 100m scale for calculation
    maxPixels: 1e9,
    crs: 'EPSG:4326' // Specify CRS for consistency
  }).get('B4').getInfo();

  if (qidrCount === 0 || qidrCount === null) {
    console.log("Jabal Qidr: No valid pixels after cloud masking or out of bounds.");
    console.log("C2");
    return;
  }

  const qidrMean = medianImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: jabalQidr,
    scale: 100,
    maxPixels: 1e9,
    crs: 'EPSG:4326'
  }).get('B4').getInfo();

  if (qidrMean === null || isNaN(qidrMean)) {
    console.log("Jabal Qidr: Calculation failed (mean is null/NaN).");
    console.log("C3");
    return;
  }

  // 4. Processing & Calculation for Jabal Bayda
  const baydaCount = medianImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: jabalBayda,
    scale: 100,
    maxPixels: 1e9,
    crs: 'EPSG:4326'
  }).get('B4').getInfo();

  if (baydaCount === 0 || baydaCount === null) {
    console.log("Jabal Bayda: No valid pixels after cloud masking or out of bounds.");
    console.log("C2");
    return;
  }

  const baydaMean = medianImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: jabalBayda,
    scale: 100,
    maxPixels: 1e9,
    crs: 'EPSG:4326'
  }).get('B4').getInfo();

  if (baydaMean === null || isNaN(baydaMean)) {
    console.log("Jabal Bayda: Calculation failed (mean is null/NaN).");
    console.log("C3");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Jabal Qidr - Mean Red Reflectance: ${qidrMean.toFixed(4)} (Pixels: ${qidrCount})`);
  console.log(`Jabal Bayda - Mean Red Reflectance: ${baydaMean.toFixed(4)} (Pixels: ${baydaCount})`);

  // "Darker color" implies lower reflectance.
  if (qidrMean < baydaMean) {
    console.log("A"); // Yes, Jabal Qidr is darker
  } else {
    console.log("B"); // No, Jabal Qidr is not darker or is the same
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
